import { Client, Wallet } from "xrpl";

import { optIntoIssuance } from "./holder";
import { MptIssuer } from "./mptIssuer";
import { submitAndAssertSuccess } from "./txSubmit";

async function tryPay(label: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
    console.log(`${label}: SUCCEEDED`);
  } catch (err) {
    console.log(`${label}: FAILED - ${(err as Error).message}`);
  }
}

async function main(): Promise<void> {
  const client = new Client("wss://s.altnet.rippletest.net:51233");
  await client.connect();

  console.log("Funding temp accounts via faucet...");
  const { wallet: tempIssuer } = await client.fundWallet();
  const { wallet: holderX } = await client.fundWallet();
  const { wallet: holderY } = await client.fundWallet();
  console.log("issuer", tempIssuer.address, "X", holderX.address, "Y", holderY.address);

  const issuer = new MptIssuer(client, tempIssuer);
  const issuanceId = await issuer.createIssuance({
    ticker: "PRB",
    name: "Probe Token",
    issuerName: "Probe Inc",
    icon: "https://example.com/icon.png",
  });
  console.log("issuance", issuanceId);

  for (const w of [holderX, holderY]) {
    await optIntoIssuance(client, w, issuanceId);
    await issuer.approveHolder(w.address);
  }
  await issuer.send(holderX.address, 100);
  await issuer.send(holderY.address, 100);
  console.log("distributed 100 to X and Y");

  console.log("\n--- Individual freeze on X ---");
  await issuer.freezeHolder(holderX.address);
  await tryPay("issuer -> frozen X", () => issuer.send(holderX.address, 1));
  await tryPay("frozen X -> Y", () =>
    submitAndAssertSuccess(client, holderX, {
      TransactionType: "Payment",
      Account: holderX.address,
      Destination: holderY.address,
      Amount: { mpt_issuance_id: issuanceId, value: "1" },
    }).then(() => undefined),
  );
  await tryPay("Y -> frozen X", () =>
    submitAndAssertSuccess(client, holderY, {
      TransactionType: "Payment",
      Account: holderY.address,
      Destination: holderX.address,
      Amount: { mpt_issuance_id: issuanceId, value: "1" },
    }).then(() => undefined),
  );
  await issuer.unfreezeHolder(holderX.address);

  console.log("\n--- Global freeze ---");
  await issuer.freezeGlobal();
  await tryPay("issuer -> X during global freeze", () => issuer.send(holderX.address, 1));
  await tryPay("X -> Y during global freeze", () =>
    submitAndAssertSuccess(client, holderX, {
      TransactionType: "Payment",
      Account: holderX.address,
      Destination: holderY.address,
      Amount: { mpt_issuance_id: issuanceId, value: "1" },
    }).then(() => undefined),
  );
  await issuer.unfreezeGlobal();

  console.log("\n--- Ban-style revoke on Y (no clawback, just unauthorize) ---");
  await issuer.revokeHolderApproval(holderY.address);
  await tryPay("issuer -> unauthorized Y", () => issuer.send(holderY.address, 1));

  await client.disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});

